package codec

import _ "embed"

// validityBitmap is the build-time validity artifact, generated by
// cmd/genvectors and shipped to the frontend as /codec/validity.bin.
//
// Embedding it removes ~500k map operations from every server start and, more
// importantly, guarantees the server and the browser read byte-identical
// inputs. A test asserts it equals ComputeValidity().
//
//go:embed tables/validity.bin
var validityBitmap []byte

// EmbeddedValidity returns the shipped bitmap.
func EmbeddedValidity() (*Validity, error) { return LoadValidity(validityBitmap) }

// EmbeddedValidityBytes exposes the raw artifact for hashing.
func EmbeddedValidityBytes() []byte { return validityBitmap }
